+import assert from 'node:assert/strict';
+
+import { canAdd } from '../src/lib/selection.ts';
+
+const portrait = { portrait: true };
+const landscape = { portrait: false };
+
+test('allows a portrait when none is selected', () => {
+  assert.equal(canAdd([], portrait), true);
+});
+
+test('rejects a second portrait', () => {
+  assert.equal(canAdd([portrait], portrait), false);
+});
+
+test('allows a second landscape', () => {
+  assert.equal(canAdd([landscape], landscape), true);
+});
+
+test('rejects a third landscape', () => {
+  assert.equal(canAdd([landscape, landscape], landscape), false);
+});
+
+test('counts portrait and landscape selections independently', () => {
+  assert.equal(canAdd([portrait], landscape), true);
+  assert.equal(canAdd([landscape, landscape], portrait), true);
+});
